// ui-general · кейсы ui-06, ui-07 (.qa/tests/ui-general/) — תשלומים חלקיים מצטברים + הכנסות/חוב פתוח בלוח הבקרה
// beforeAll: buyer сам создаёт заказ «QA-AUTO-ui-general-e2e-…» (6 × מצית קליפט = ₪30). Реальные заказы не трогаются.
// Корзина buyer общая на сервере → не запускать параллельно с orders/order-lifecycle.spec.ts и client-ordering/cart-checkout.spec.ts.
// KPI дашборда общие для компании: сравниваются дельты сразу до/после действия (параллельные заказы других прогонов могут мешать).
import { test, expect, Page, Browser } from '@playwright/test';
import * as path from 'path';

const auth = (role: string) => path.resolve(__dirname, '../../../auth', `${role}.json`);
test.use({ storageState: auth('admin') });
test.describe.configure({ mode: 'serial' });

const ITEM = { id: '340b7b2b-e022-4f3b-a6f0-f9a3dc8ecfe8', name: 'מצית קליפט' }; // ₪5.00 у клиента test
const QTY = 6;
const TOTAL = QTY * 5;
let orderNo = '';

async function buyerPlaceOrder(browser: Browser): Promise<string> {
  const ctx = await browser.newContext({ storageState: auth('buyer') });
  const page = await ctx.newPage();
  await page.goto('/shop/cart');
  await expect(page.getByRole('heading', { name: 'העגלה שלי' })).toBeVisible();
  const remove = page.getByRole('button', { name: /^הסרה מהעגלה/ });
  // ждём, пока корзина загрузится (staging бывает медленным): либо есть позиции, либо «העגלה ריקה»
  await expect(remove.first().or(page.getByText('העגלה ריקה'))).toBeVisible({ timeout: 20_000 });
  while (await remove.count()) {
    await remove.first().click();
    await page.waitForTimeout(500);
  }
  await page.goto(`/shop/p/${ITEM.id}`);
  await page.getByRole('button', { name: /^הוסף לעגלה/ }).click();
  await page.goto('/shop/cart');
  for (let i = 1; i < QTY; i++) await page.getByRole('button', { name: `הוספת יחידה — ${ITEM.name}` }).click();
  await expect(page.getByText('סה״כ משוער').locator('..')).toContainText(`₪${TOTAL.toFixed(2)}`);
  await page.getByRole('button', { name: 'המשך לביצוע הזמנה' }).click();
  await page.getByRole('textbox', { name: 'הערות להזמנה' }).fill(`QA-AUTO-ui-general-e2e-${Date.now()}`);
  await page.getByRole('button', { name: 'שליחת הזמנה' }).click();
  await expect(page.getByRole('heading', { name: 'ההזמנה נקלטה!' })).toBeVisible({ timeout: 20_000 });
  const no = (await page.getByText(/^הזמנה\s*#\d+/).first().innerText()).match(/#(\d+)/)![1];
  await ctx.close();
  return no;
}

type Kpi = { revenue: number; openOrders: number; debt: number };
async function readKpi(page: Page): Promise<Kpi> {
  await page.goto('/dashboard');
  await expect(page.getByText('חוב פתוח', { exact: true })).toBeVisible({ timeout: 20_000 });
  await page.getByRole('combobox', { name: 'תקופה' }).selectOption({ label: '7 הימים האחרונים' });
  await page.getByRole('combobox', { name: 'היקף' }).selectOption({ label: 'כל החברה' });
  // карточки KPI должны быть отрисованы (после смены фильтров) до чтения значений; короткая пауза — дать данным обновиться
  await expect(page.getByText('הזמנות פתוחות', { exact: true }).first().locator('../..')).toContainText(/נכון לעכשיו\s*\d+/, { timeout: 20_000 });
  await page.waitForTimeout(2000);
  const card = async (label: string) => (await page.getByText(label, { exact: true }).first().locator('../..').innerText()).replace(/\s+/g, ' ');
  const money = (s: string) => Number((s.match(/₪([\d,]+(?:\.\d+)?)/) || ['', '0'])[1].replace(/,/g, ''));
  const open = await card('הזמנות פתוחות');
  return { revenue: money(await card('הכנסות')), openOrders: Number(open.match(/נכון לעכשיו (\d+)/)![1]), debt: money(await card('חוב פתוח')) };
}

async function openOrder(page: Page, no: string) {
  await page.goto('/orders');
  await page.getByRole('combobox', { name: 'סינון לפי חודש' }).selectOption({ label: 'כל החודשים' });
  const orderRow = page.getByRole('button', { name: new RegExp(`^#${no} `) });
  await expect(orderRow).toBeVisible({ timeout: 20_000 });
  await orderRow.click();
  await expect(page.getByRole('heading', { level: 1, name: `הזמנה #${no}` })).toBeVisible({ timeout: 20_000 });
}

const payBox = (page: Page) => page.getByRole('heading', { name: 'סטטוס תשלום' }).locator('../..');
const header = (page: Page) => page.getByRole('heading', { level: 1 }).locator('..');

async function partial(page: Page, amount: string) {
  const box = payBox(page);
  await box.getByRole('button', { name: 'עדכון' }).click();
  await box.getByRole('combobox', { name: 'סטטוס תשלום' }).selectOption({ label: 'שולם חלקית' });
  await box.getByRole('textbox', { name: 'סכום שהתקבל כעת' }).fill(amount);
  await box.getByRole('button', { name: 'שמירה' }).click();
}

test.describe('ui-general — תשלומים חלקיים ולוח בקרה (QA-AUTO)', () => {
  let before: Kpi;

  test.beforeAll(async ({ browser }) => {
    test.setTimeout(180_000);
    const ctx = await browser.newContext({ storageState: auth('admin') });
    const page = await ctx.newPage();
    before = await readKpi(page);
    await ctx.close();
    orderNo = await buyerPlaceOrder(browser);
  });

  test.afterAll(async ({ browser }) => {
    if (!orderNo) return;
    const ctx = await browser.newContext({ storageState: auth('admin') });
    const page = await ctx.newPage();
    await openOrder(page, orderNo);
    if (await page.getByRole('button', { name: 'דחייה' }).count()) {
      await page.getByRole('button', { name: 'דחייה' }).click();
      await page.getByRole('dialog').getByRole('textbox', { name: 'סיבת הדחייה *' }).fill('QA-AUTO cleanup');
      await page.getByRole('dialog').getByRole('button', { name: 'דחה הזמנה' }).click();
    }
    await ctx.close();
  });

  test('הזמנה שלא שולמה: לפני אישור — לא בחוב; אחרי אישור — חוב +סכום, הכנסות +0 #6a730131 @desktop', async ({ page }) => {
    const pending = await readKpi(page);
    expect(pending.openOrders).toBeGreaterThanOrEqual(before.openOrders + 1);
    expect(pending.debt).toBe(before.debt);
    expect(pending.revenue).toBe(before.revenue);

    await openOrder(page, orderNo);
    await page.getByRole('button', { name: 'אישור הזמנה' }).click();
    await page.getByRole('dialog').getByRole('textbox', { name: 'הערה (לא חובה)' }).fill('QA-AUTO-ui-general approve');
    await page.getByRole('dialog').getByRole('button', { name: 'אשר הזמנה' }).click();
    await expect(header(page)).toContainText('אושרה · ממתינה לליקוט', { timeout: 20_000 });
    await expect(header(page)).toContainText('לא שולם');

    const approved = await readKpi(page);
    expect(approved.debt).toBe(pending.debt + TOTAL);
    expect(approved.revenue).toBe(pending.revenue);
  });

  test('תשלומים חלקיים מצטברים, חריגה נחסמת, ביתרה 0 — «שולם»; הכנסות/חוב זזים בהתאם #6a74975a #6a730131 @desktop', async ({ page }) => {
    const step = TOTAL / 3;
    const fmt = (n: number) => `₪${n.toFixed(2)}`;
    let k = await readKpi(page);
    for (let i = 1; i <= 3; i++) {
      await openOrder(page, orderNo);
      const box = payBox(page);
      if (i === 2) {
        await box.getByRole('button', { name: 'עדכון' }).click();
        await box.getByRole('combobox', { name: 'סטטוס תשלום' }).selectOption({ label: 'שולם חלקית' });
        await expect(box.getByText(`סכום שהתקבל כעת (עד ${fmt(TOTAL - step)} שנותרו)`)).toBeVisible();
        await box.getByRole('textbox', { name: 'סכום שהתקבל כעת' }).fill((TOTAL - step + 0.01).toFixed(2));
        await expect(box.getByText(`הסכום גבוה מהיתרה שנותרה — ${fmt(TOTAL - step)}`)).toBeVisible();
        await expect(box.getByRole('button', { name: 'שמירה' })).toBeDisabled();
        await box.getByRole('button', { name: 'ביטול' }).click();
      }
      await partial(page, String(step));
      const paid = step * i;
      await expect(box).toContainText(`${fmt(paid)} מתוך ${fmt(TOTAL)}`, { timeout: 20_000 });
      await expect(page.getByText('נותר לתשלום').locator('..')).toContainText(fmt(TOTAL - paid));
      if (i < 3) await expect(header(page)).toContainText('שולם חלקית');
      const after = await readKpi(page);
      expect(after.revenue).toBe(k.revenue + step);
      expect(after.debt).toBe(k.debt - step);
      k = after;
    }
    await openOrder(page, orderNo);
    await expect(payBox(page)).toContainText(`${fmt(TOTAL)} מתוך ${fmt(TOTAL)}`);
    await expect(header(page)).toContainText(/שולם(?! חלקית)/);
    await expect(header(page)).not.toContainText('שולם חלקית');
    await expect(page.getByText('נותר לתשלום').locator('..')).toContainText('₪0.00');
  });

  test('השלמת ההזמנה: מוכן למשלוח → בדרך ללקוח → סופק, נשאר «שולם» #6a74975a @desktop', async ({ page }) => {
    await openOrder(page, orderNo);
    await page.getByRole('button', { name: 'סמן כמוכנה למשלוח' }).click();
    await expect(header(page)).toContainText('מוכנה למשלוח', { timeout: 20_000 });
    await page.getByRole('button', { name: 'סמן כיצאה למשלוח' }).click();
    await expect(header(page)).toContainText('בדרך ללקוח', { timeout: 20_000 });
    await page.getByRole('button', { name: 'סמן כסופקה' }).click();
    await expect(header(page)).toContainText('סופקה', { timeout: 20_000 });
    await expect(header(page)).not.toContainText('שולם חלקית');
  });
});
